        return typedData.toFloat64Array()
      default:
        return typedData
      }
    }
    if value is NSNumber {
      let number = value as! NSNumber
      if type == "int" || type == "int64" {
        return number.int64Value
      } else if type == "double" {
        return number.doubleValue
      } else if type == "bool" {
        return number.boolValue
      }
             else if (type == "NativeAspectRatioMode") {
        return NativeAspectRatioMode.init(rawValue: number.intValue)
      }       else if (type == "NativeCastState") {
        return NativeCastState.init(rawValue: number.intValue)
      }       else if (type == "NativePlayerEventType") {
        return NativePlayerEventType.init(rawValue: number.intValue)
      }
      
      return number.int64Value
    }
    if (value is NSMutableArray || value is NSArray) {
      var res: Array<Any?> = []
      for item in (value as! NSArray) {
          res.append(readValue(value: item as? NSObject, type: type))
      }
      return res
    }
    if (value is NSDictionary) {
      var res: Dictionary<AnyHashable?, Any?> = Dictionary()
      for (key, value) in (value as! NSDictionary) {
          res[readValue(value: key as? NSObject, type: type) as? AnyHashable] = readValue(value: value as? NSObject, type: type2)
      }
      return res
    } 
    if (value is PlayerApiNumberWrapper) {
      return unwrapNumber(wrappedNumber: value as! PlayerApiNumberWrapper)
    }
    if (value is NSString) {
      return value as! NSString
          } else if (value is OpenMediaRequestBridge) {
        return (value! as! OpenMediaRequestBridge).toSwift();
              } else if (value is DurationProbeRequestBridge) {
        return (value! as! DurationProbeRequestBridge).toSwift();
              } else if (value is CoverExtractRequestBridge) {
        return (value! as! CoverExtractRequestBridge).toSwift();
              } else if (value is CoverFrameDataBridge) {
        return (value! as! CoverFrameDataBridge).toSwift();
              } else if (value is SnapshotDataBridge) {
        return (value! as! SnapshotDataBridge).toSwift();
              } else if (value is CacheConfigRequestBridge) {
        return (value! as! CacheConfigRequestBridge).toSwift();
              } else if (value is PrecacheRequestBridge) {
        return (value! as! PrecacheRequestBridge).toSwift();
              } else if (value is CacheEntryRequestBridge) {
        return (value! as! CacheEntryRequestBridge).toSwift();
              } else if (value is PlayerEventDataBridge) {
        return (value! as! PlayerEventDataBridge).toSwift();
        
    }
    return value
  }

  static func writeValue(value: Any?, isObject: Bool = false) -> Any? {
    if (PlayerApiPigeonInternal.isNullish(value)) {
      return PlayerApiPigeonInternalNull()
    }
    if let uint8Array = value as? [UInt8] {
      return isObject ? PlayerApiPigeonTypedData(uint8Array) : uint8Array as NSArray
    }
    if let int32Array = value as? [Int32] {
      return isObject ? PlayerApiPigeonTypedData(int32Array) : int32Array as NSArray
    }
    if let int64Array = value as? [Int64] {
      return isObject ? PlayerApiPigeonTypedData(int64Array) : int64Array as NSArray
    }
    if let float32Array = value as? [Float32] {
      return isObject ? PlayerApiPigeonTypedData(float32Array) : float32Array as NSArray
    }
    if let float64Array = value as? [Double] {
      return isObject ? PlayerApiPigeonTypedData(float64Array) : float64Array as NSArray
    }
    if (value is Bool || value is Double || value is Int || value is Int64 || value is NativeAspectRatioMode || value is NativeCastState || value is NativePlayerEventType) {
      if (isObject) {
        return wrapNumber(number: value!)
      }
      if (value is Bool) {
        return value
      } else if (value is Double) {
        return value
      } else if (value is Int || value is Int64) {
        return value
      }
            else if (value is NativeAspectRatioMode) {
        return (value as! NativeAspectRatioMode).rawValue
      }      else if (value is NativeCastState) {
        return (value as! NativeCastState).rawValue
      }      else if (value is NativePlayerEventType) {
        return (value as! NativePlayerEventType).rawValue
      }
    }
    if (value is [Any]) {
      let list = value as! [Any]
      let res: NSMutableArray = NSMutableArray(capacity: list.count)
      for item in list {
        res.add(PlayerApiPigeonInternal.isNullish(item) ? PlayerApiPigeonInternalNull() : writeValue(value: item, isObject: true) as! NSObject)
      }
      return res
    }
    if (value is [AnyHashable: Any]) {
      let dict = value as! [AnyHashable: Any]
      let res: NSMutableDictionary = NSMutableDictionary(capacity: dict.count)
      for (key, value) in dict {
         res.setObject(PlayerApiPigeonInternal.isNullish(value) ? PlayerApiPigeonInternalNull() : writeValue(value: value, isObject: true) as! NSObject, forKey: writeValue(value: key, isObject: true) as! NSCopying)
      }
      return res
    }
    if (value is String) {
      return value as! NSString
          } else if (value is OpenMediaRequest) {
        return OpenMediaRequestBridge.fromSwift(value as? OpenMediaRequest);
              } else if (value is DurationProbeRequest) {
        return DurationProbeRequestBridge.fromSwift(value as? DurationProbeRequest);
              } else if (value is CoverExtractRequest) {
        return CoverExtractRequestBridge.fromSwift(value as? CoverExtractRequest);
              } else if (value is CoverFrameData) {
        return CoverFrameDataBridge.fromSwift(value as? CoverFrameData);
              } else if (value is SnapshotData) {
        return SnapshotDataBridge.fromSwift(value as? SnapshotData);
              } else if (value is CacheConfigRequest) {
        return CacheConfigRequestBridge.fromSwift(value as? CacheConfigRequest);
              } else if (value is PrecacheRequest) {
        return PrecacheRequestBridge.fromSwift(value as? PrecacheRequest);
              } else if (value is CacheEntryRequest) {
        return CacheEntryRequestBridge.fromSwift(value as? CacheEntryRequest);
              } else if (value is PlayerEventData) {
        return PlayerEventDataBridge.fromSwift(value as? PlayerEventData);
        
    }
    return value
