      return
    }
    writeByte(PlayerApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeValue(key)
      writeValue(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K?: V]?) {
    guard let map = map else {
      writeByte(PlayerApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(PlayerApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeOptional(key)
      writeValue(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K: V?]?) {
    guard let map = map else {
      writeByte(PlayerApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(PlayerApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeValue(key)
      writeOptional(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K?: V?]?) {
    guard let map = map else {
      writeByte(PlayerApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(PlayerApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeOptional(key)
      writeOptional(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K: V]?, _ writeEntry: (inout Self, K, V) -> Void) {
    guard let map = map else {
      writeByte(PlayerApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(PlayerApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeEntry(&self, key, item)
    }
  }


  mutating func writeOpenMediaRequest(_ value: OpenMediaRequest) {
    writeByte(PlayerApiPigeonInteropCodec.typeList)
    writeSize(5)
    writeValue(value.url)
    writeValue(value.castUrl)
    writeValue(value.cacheKey)
    writeMap(value.headers)
    writeValue(value.enableCache)
  }

  mutating func writeDurationProbeRequest(_ value: DurationProbeRequest) {
    writeByte(PlayerApiPigeonInteropCodec.typeList)
