      return true
    }
    if valueType == NativePlayerEventType.self {
      writeByte(131)
      writeValue(Int64((value as! NativePlayerEventType).rawValue))
      return true
    }
    if valueType == OpenMediaRequest.self {
      writeByte(132)
      writeOpenMediaRequest((value as! OpenMediaRequest))
      return true
    }
    if valueType == DurationProbeRequest.self {
      writeByte(133)
      writeDurationProbeRequest((value as! DurationProbeRequest))
      return true
    }
    if valueType == CoverExtractRequest.self {
      writeByte(134)
