  mutating func writeCustomValueFallback(_ value: Any) -> Bool {
    if let value = value as? NativeAspectRatioMode {
      writeByte(129)
      writeValue(Int64(value.rawValue))
      return true
    }
    if let value = value as? NativeCastState {
      writeByte(130)
