/// Unwraps optionals that a generic context boxed into `Any`.
private protocol PlayerApiPigeonInteropOptional {
  var pigeonWrapped: Any? { get }
}

extension Optional: PlayerApiPigeonInteropOptional {
  fileprivate var pigeonWrapped: Any? {
    switch self {
    case .some(let wrapped):
      return wrapped
    case .none:
      return nil
    }
  }
}

/// Writes typed lists without converting them to `[Any?]` first.
private protocol PlayerApiPigeonInteropList {
  func pigeonWrite(to writer: inout PlayerApiPigeonInteropWriter)
}

extension Array: PlayerApiPigeonInteropList {
  fileprivate func pigeonWrite(to writer: inout PlayerApiPigeonInteropWriter) {
    writer.writeByte(PlayerApiPigeonInteropCodec.typeList)
    writer.writeSize(count)
    for item in self {
      writer.writeValue(item)
    }
  }
}

/// Writes typed maps without converting them to `[AnyHashable?: Any?]` first.
private protocol PlayerApiPigeonInteropMap {
  func pigeonWrite(to writer: inout PlayerApiPigeonInteropWriter)
}

extension Dictionary: PlayerApiPigeonInteropMap {
  fileprivate func pigeonWrite(to writer: inout PlayerApiPigeonInteropWriter) {
    writer.writeByte(PlayerApiPigeonInteropCodec.typeMap)
    writer.writeSize(count)
    for (key, item) in self {
      writer.writeValue(key)
      writer.writeValue(item)
    }
  }
}


/// Reads values in the format of Flutter's standard message codec.
private struct PlayerApiPigeonInteropReader {
  private let data: NSData
  private let bytes: UnsafeRawBufferPointer
  private var position = 0

  init(_ data: NSData) {
    self.data = data
    self.bytes = UnsafeRawBufferPointer(start: data.bytes, count: data.length)
  }

  var isAtEnd: Bool { position >= bytes.count }

  mutating func readByte() -> UInt8 {
    let byte = bytes[position]
    position += 1
    return byte
  }

  mutating func readRaw<T: FixedWidthInteger>(_ type: T.Type) -> T {
    let value = bytes.loadUnaligned(fromByteOffset: position, as: T.self)
    position += MemoryLayout<T>.size
    return T(littleEndian: value)
  }

  mutating func readSize() -> Int {
    let byte = readByte()
    if byte < PlayerApiPigeonInteropCodec.sizeUInt16 {
      return Int(byte)
    } else if byte == PlayerApiPigeonInteropCodec.sizeUInt16 {
      return Int(readRaw(UInt16.self))
    }
    return Int(readRaw(UInt32.self))
  }

  mutating func readAlignment(_ alignment: Int) {
    let mod = position % alignment
    if mod != 0 {
      position += alignment - mod
    }
  }

  mutating func readTypedData<T>(_ type: T.Type, alignment: Int) -> [T] {
    let count = readSize()
    readAlignment(alignment)
    let byteCount = count * MemoryLayout<T>.stride
    let result = [T](unsafeUninitializedCapacity: count) { buffer, initializedCount in
      if byteCount > 0 {
        UnsafeMutableRawBufferPointer(buffer).copyMemory(
          from: UnsafeRawBufferPointer(rebasing: bytes[position..<(position + byteCount)]))
      }
      initializedCount = count
    }
    position += byteCount
    return result
  }

  mutating func readValue() -> Any? {
    return readValue(ofType: readByte())
  }

  mutating func readValue(ofType type: UInt8) -> Any? {
    switch type {
    case PlayerApiPigeonInteropCodec.typeNull:
      return nil
    case PlayerApiPigeonInteropCodec.typeTrue:
      return true
    case PlayerApiPigeonInteropCodec.typeFalse:
      return false
    case PlayerApiPigeonInteropCodec.typeInt32:
      return Int64(readRaw(Int32.self))
    case PlayerApiPigeonInteropCodec.typeInt64:
      return readRaw(Int64.self)
    case PlayerApiPigeonInteropCodec.typeLargeInt, PlayerApiPigeonInteropCodec.typeString:
      let count = readSize()
      let string = String(
        decoding: UnsafeRawBufferPointer(rebasing: bytes[position..<(position + count)]),
        as: UTF8.self)
      position += count
      return string
    case PlayerApiPigeonInteropCodec.typeFloat64:
      readAlignment(8)
      return Double(bitPattern: readRaw(UInt64.self))
    case PlayerApiPigeonInteropCodec.typeUint8List:
      return readTypedData(UInt8.self, alignment: 1)
    case PlayerApiPigeonInteropCodec.typeInt32List:
      return readTypedData(Int32.self, alignment: 4)
    case PlayerApiPigeonInteropCodec.typeInt64List:
      return readTypedData(Int64.self, alignment: 8)
    case PlayerApiPigeonInteropCodec.typeFloat64List:
      return readTypedData(Float64.self, alignment: 8)
    case PlayerApiPigeonInteropCodec.typeList:
      let count = readSize()
      var list: [Any?] = []
      list.reserveCapacity(count)
      for _ in 0..<count {
        list.append(readValue())
      }
      return list
    case PlayerApiPigeonInteropCodec.typeMap:
      let count = readSize()
      var map: [AnyHashable?: Any?] = [:]
      map.reserveCapacity(count)
      for _ in 0..<count {
        let key = readValue() as? AnyHashable
        map[key] = readValue()
      }
      return map
    case PlayerApiPigeonInteropCodec.typeFloat32List:
      return readTypedData(Float32.self, alignment: 4)
    default:
      return readCustomValue(ofType: type)
    }
  }

  mutating func readListHeader() {
    _ = readByte()
    _ = readSize()
  }

  mutating func read<T>(_ type: T.Type) -> T {
    return readValue() as! T
  }

  mutating func read<E>(_ type: [E].Type) -> [E] {
    let tag = readByte()
    guard tag == PlayerApiPigeonInteropCodec.typeList else {
      return readValue(ofType: tag) as! [E]
    }
    let count = readSize()
    var list: [E] = []
    list.reserveCapacity(count)
    for _ in 0..<count {
      list.append(readValue() as! E)
    }
    return list
  }

  mutating func read<E>(_ type: [E]?.Type) -> [E]? {
    if bytes[position] == PlayerApiPigeonInteropCodec.typeNull {
      position += 1
      return nil
    }
    return read([E].self)
  }

  mutating func read<K: Hashable, V>(_ type: [K: V].Type) -> [K: V] {
    let tag = readByte()
    guard tag == PlayerApiPigeonInteropCodec.typeMap else {
      return readValue(ofType: tag) as! [K: V]
    }
    let count = readSize()
    var map: [K: V] = [:]
    map.reserveCapacity(count)
    for _ in 0..<count {
      let key = readValue() as! K
      map[key] = (readValue() as! V)
    }
    return map
  }

  mutating func read<K: Hashable, V>(_ type: [K: V]?.Type) -> [K: V]? {
    if bytes[position] == PlayerApiPigeonInteropCodec.typeNull {
      position += 1
      return nil
    }
    return read([K: V].self)
  }


