  mutating func readCustomValue(ofType type: UInt8) -> Any? {
    switch type {
    case 129:
      guard let raw = readValue() as? Int64 else { return nil }
      return NativeAspectRatioMode(rawValue: Int(raw))
    case 130:
      guard let raw = readValue() as? Int64 else { return nil }
      return NativeCastState(rawValue: Int(raw))
    case 131:
      guard let raw = readValue() as? Int64 else { return nil }
      return NativePlayerEventType(rawValue: Int(raw))
    case 132:
      return readOpenMediaRequest()
    case 133:
