  fileprivate static func register(api: PlayerHostApi, engineKey: Int64, name: String) {
    PlayerHostApiInstanceTracker.lock.lock()
    defer { PlayerHostApiInstanceTracker.lock.unlock() }
    var list = PlayerHostApiInstanceTracker.instancesOfPlayerHostApi[name] ?? []
    if let index = list.firstIndex(where: { $0.api === api && $0.engineKey == engineKey }) {
      list.append(list.remove(at: index))
    } else {
      let wrapper = PlayerHostApiSetup()
      wrapper.engineKey = engineKey
      wrapper.api = api
      list.append(wrapper)
    }
    PlayerHostApiInstanceTracker.instancesOfPlayerHostApi[name] = list
  }

  fileprivate static func unregister(api: PlayerHostApi, engineKey: Int64, name: String) {
    // Removed entries are kept alive until after unlocking so their deinit cannot run while the
    // non-recursive lock is held.
    var displaced: [Any] = []
    do {
      PlayerHostApiInstanceTracker.lock.lock()
      defer { PlayerHostApiInstanceTracker.lock.unlock() }
      guard var list = PlayerHostApiInstanceTracker.instancesOfPlayerHostApi[name] else {
        return
      }
      let removeKey: Int64
      if list.contains(where: { $0.api === api && $0.engineKey == engineKey }) {
        removeKey = engineKey
      } else {
        let keys = Set(list.filter { $0.api === api }.map { $0.engineKey })
        guard keys.count == 1, let onlyKey = keys.first else {
          return
        }
        removeKey = onlyKey
      }
      list.removeAll { entry in
        guard let existing = entry.api else {
          return false
        }
        if existing === api && entry.engineKey == removeKey {
          displaced.append(existing)
          displaced.append(entry)
          entry.api = nil
          return true
        }
        return false
      }
      if list.isEmpty {
        PlayerHostApiInstanceTracker.instancesOfPlayerHostApi.removeValue(forKey: name)
      } else {
        PlayerHostApiInstanceTracker.instancesOfPlayerHostApi[name] = list
