  @objc static func pigeonResolveInstance(engineId: Int64, affinityKey: Int64, name: String = PlayerApiPigeonInternal.defaultInstanceName) -> PlayerHostApiSetup? {
    PlayerHostApiInstanceTracker.lock.lock()
    defer { PlayerHostApiInstanceTracker.lock.unlock() }
    guard let list = PlayerHostApiInstanceTracker.instancesOfPlayerHostApi[name] else {
      return nil
    }
    if engineId != Int64.min, let match = list.last(where: { $0.engineKey == engineId }) {
      return match
    }
    if affinityKey != Int64.min, let match = list.last(where: { $0.engineKey == affinityKey }) {
      return match
    }
    return list.last
  }

  /// Returns the engine key `instance` was registered with, or `Int64.min` if unknown.
  @objc static func pigeonEngineKey(of instance: PlayerHostApiSetup) -> Int64 {
    return instance.engineKey
  }
