/// Generated protocol from Pigeon that represents Flutter messages that can be called from Swift.
@objc protocol PlayerFlutterApiBridge {
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onPlayerEvent(pigeonVar_args: NSData, error: PigeonError) async
  @objc func onWindowFullscreen(isFullscreen isFullscreenArg: Bool, error: PigeonError) async
}

@objc class PlayerFlutterApiRegistrar: NSObject {
  static var registeredPlayerFlutterApi = [String: [PlayerFlutterApi]]()
  /// Guards the registrations, which Native Interop calls can read from any thread.
  static let lock = NSLock()

  /// Registers the Dart implementation `api` under `name` (or the default instance
  /// when `name` is omitted).
  ///
  /// Called by generated Dart code. `engineId` and `affinityKey` identify the engine
  /// that registered `api`, or are `Int64.min` when unknown.
  /// Registering an instance that is already registered under `name` updates its
  /// keys and keeps its position.
  @objc static func registerInstance(api: PlayerFlutterApiBridge, engineId: Int64, affinityKey: Int64, name: String = PlayerApiPigeonInternal.defaultInstanceName) {
    let apiObject = api as AnyObject
    PlayerFlutterApiRegistrar.lock.lock()
    defer { PlayerFlutterApiRegistrar.lock.unlock() }
    var list = PlayerFlutterApiRegistrar.registeredPlayerFlutterApi[name] ?? []
    let registration = PlayerFlutterApi(api: api, engineId: engineId, affinityKey: affinityKey)
    if let index = list.firstIndex(where: { ($0.api as AnyObject) === apiObject }) {
      list[index] = registration
    } else {
      list.append(registration)
    }
    PlayerFlutterApiRegistrar.registeredPlayerFlutterApi[name] = list
  }

  /// Removes `api` from the registrations under `name` (or the default instance
  /// when `name` is omitted), leaving other registrations in place.
  ///
  /// Instances are matched by identity. Does nothing if `api` is not registered.
  @objc static func unregisterInstance(api: PlayerFlutterApiBridge, name: String = PlayerApiPigeonInternal.defaultInstanceName) {
    let apiObject = api as AnyObject
    // Removed entries are kept alive until after unlocking so their deinit cannot run while the
    // non-recursive lock is held.
    var displaced: [PlayerFlutterApi] = []
    do {
      PlayerFlutterApiRegistrar.lock.lock()
      defer { PlayerFlutterApiRegistrar.lock.unlock() }
      guard var list = PlayerFlutterApiRegistrar.registeredPlayerFlutterApi[name] else {
        return
      }
      list.removeAll { entry in
        if (entry.api as AnyObject) === apiObject {
          displaced.append(entry)
          return true
        }
        return false
      }
      if list.isEmpty {
        PlayerFlutterApiRegistrar.registeredPlayerFlutterApi.removeValue(forKey: name)
      } else {
        PlayerFlutterApiRegistrar.registeredPlayerFlutterApi[name] = list
      }
    }
    withExtendedLifetime(displaced) {}
  }

  #if canImport(Flutter) || canImport(FlutterMacOS)
    /// Returns the instance for `name` (or the default instance when `name` is omitted)
    /// that was registered from the engine that owns `registrar`.
    ///
    /// When no instance is known to belong to that engine, falls back to the most
    /// recent registration for `name`. Returns nil if none is registered.
    static func getInstance(registrar: FlutterPluginRegistrar, name: String = PlayerApiPigeonInternal.defaultInstanceName) -> PlayerFlutterApi? {
      return getInstance(engineKey: PigeonEngineKeys.key(for: registrar), name: name)
    }
  #endif

  fileprivate static func getInstance(engineKey: Int64, name: String) -> PlayerFlutterApi? {
    PlayerFlutterApiRegistrar.lock.lock()
    defer { PlayerFlutterApiRegistrar.lock.unlock() }
    guard let list = PlayerFlutterApiRegistrar.registeredPlayerFlutterApi[name] else {
      return nil
    }
    if engineKey != Int64.min, let match = list.last(where: { $0.engineId == engineKey }) ?? list.last(where: { $0.affinityKey == engineKey }) {
      return match
    }
    return list.last
  }
}

class PlayerFlutterApi {
  fileprivate let api: PlayerFlutterApiBridge
  fileprivate let engineId: Int64
  fileprivate let affinityKey: Int64

  fileprivate init(api: PlayerFlutterApiBridge, engineId: Int64, affinityKey: Int64) {
    self.api = api
    self.engineId = engineId
    self.affinityKey = affinityKey
  }

  func onPlayerEvent(event eventArg: PlayerEventData) async throws {
    let error = PigeonError()
    await api.onPlayerEvent(pigeonVar_args: PlayerApiPigeonInteropCodec.encode { $0.writeByte(PlayerApiPigeonInteropCodec.typeList); $0.writeSize(1); $0.writeValue(eventArg) }, error: error)
    if (error.code != nil) {
      throw error
    }
  }

  func onWindowFullscreen(isFullscreen isFullscreenArg: Bool) async throws {
    let error = PigeonError()
    await api.onWindowFullscreen(isFullscreen: isFullscreenArg, error: error)
    if (error.code != nil) {
      throw error
    }
  }
}
